import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const m=JSON.parse('{"title":"NoCRM","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/nocrm.md","filePath":"integrations/crm/nocrm.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/nocrm.md"};function a(l,t,s,c,h,g){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="nocrm" tabindex="-1">NoCRM <a class="header-anchor" href="#nocrm" aria-label="Permalink to &quot;NoCRM&quot;">​</a></h1><p>Follow the below steps to connect to the NoCRM API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select NoCRM as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-nocrm-api" tabindex="-1">Step 2. Connect to the NoCRM API <a class="header-anchor" href="#step-2-connect-to-the-nocrm-api" aria-label="Permalink to &quot;Step 2. Connect to the NoCRM API&quot;">​</a></h3><ol><li>Go to <a href="https://nocrm.io/" target="_blank">NoCRM</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Admin Panel</strong>.</li><li>Under <strong>Integrations</strong> click on the <strong>API Keys</strong> button.</li><li>Click the <strong>Create API Key</strong> button.</li><li>Copy the <strong>API Key</strong> from NoCRM and paste in the <strong>API Key</strong> field in Formie.</li><li>Enter the full domain (including <code>https://</code>) for your NoCRM account in the <strong>Domain</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=e(i,[["render",a]]);export{m as __pageData,p as default};
